#include <iostream>
#include <string>

class Member {
public:
    explicit Member(const std::string& name) : name_{name} {
        std::cout << "Member " << name_ << " constructed\n";
    }
    ~Member() {
        std::cout << "Member " << name_ << " destroyed\n";
    }
private:
    std::string name_;
};

class Base {
public:
    explicit Base(int val) : val_{val}, baseMember_{"BaseMember"} {
        std::cout << "Base constructor: val = " << val_ << "\n";
    }
    virtual ~Base() {
        std::cout << "Base destructor\n";
    }
private:
    int val_;
    Member baseMember_;
};

class Derived : public Base {
public:
    // C++11 / C++17 Inheriting constructors
    using Base::Base;

    ~Derived() override {
        std::cout << "Derived destructor\n";
    }
private:
    Member derivedMember_{"DerivedMember"};
};

int main() {
    std::cout << "--- Creating Derived Object ---\n";
    {
        Derived obj{42};
        std::cout << "--- Inside Scope ---\n";
    }
    std::cout << "--- Scope Exited ---\n";
    return 0;
}

#include <iostream>

class Engine {
public:
    void start() const {
        std::cout << "Engine started\n";
    }
protected:
    void injectFuel() const {
        std::cout << "Fuel injected\n";
    }
private:
    int serialNumber_{12345};
};

// Public inheritance: Car IS-A Engine (modeling-wise unusual, but demonstrates access)
class PublicVehicle : public Engine {
public:
    void drive() {
        start();       // Accessible: public in base remains public
        injectFuel();  // Accessible: protected in base remains protected
    }
};

// Private inheritance: Machine HAS-AN engine as an internal implementation detail
class PrivateMachine : private Engine {
public:
    void operate() {
        start();       // Accessible internally: becomes private in PrivateMachine
        injectFuel();  // Accessible internally: becomes private in PrivateMachine
    }
};

int main() {
    PublicVehicle car;
    car.start(); // OK: public member of public base is public
    car.drive();

    PrivateMachine machine;
    machine.operate(); // OK: operate() is public
    // machine.start(); // COMPILER ERROR: start() is private in PrivateMachine

    return 0;
}
